{
  "name": "knowledge-base",
  "version": "0.1.0",
  "description": "Electron-based personal knowledge base with document import, indexing, and grounded Q&A",
  "main": "dist/main/main.js",
  "scripts": {
    "dev": "node scripts/dev.js",
    "build": "tsc -p tsconfig.node.json && npm run build:preload && vite build",
    "build:preload": "esbuild src/preload/preload.ts --bundle --platform=node --format=cjs --external:electron --sourcemap --outfile=dist/preload/preload.js",
    "check": "tsc --noEmit -p tsconfig.node.json && tsc --noEmit -p tsconfig.json",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1",
    "uuid": "^9.0.0"
  },
  "devDependencies": {
    "@types/react": "^18.3.12",
    "@types/react-dom": "^18.3.1",
    "@types/uuid": "^9.0.7",
    "@vitejs/plugin-react": "^4.3.4",
    "electron": "^33.2.0",
    "esbuild": "^0.25.12",
    "typescript": "^5.7.0",
    "vite": "^6.0.0",
    "vitest": "^2.1.0"
  }
}
import { useEffect, useState } from 'react';
import { Document, Chunk } from '../../shared/types';

interface Props {
  document: Document;
  onDelete?: (id: string) => void;
}

export function DocumentDetail({ document, onDelete }: Props) {
  const [chunks, setChunks] = useState<Chunk[]>([]);
  const [showChunks, setShowChunks] = useState(false);
  // setContent is wired up by the document-detail feature.
  const [content] = useState<string | null>(null);

  useEffect(() => {
    window.knowledgeBase.indexing.chunks(document.id).then(setChunks);
  }, [document.id]);

  // TODO: Load document content for viewing -- not yet implemented
  // This is part of the document-detail feature to be completed.

  return (
    <div>
      <h2 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '8px' }}>
        {document.title}
      </h2>
      <div style={{ fontSize: '13px', color: '#888', marginBottom: '16px' }}>
        <div>Filename: {document.filename}</div>
        <div>Imported: {new Date(document.importedAt).toLocaleString()}</div>
        <div>Size: {(document.size / 1024).toFixed(1)} KB</div>
        <div>Status: {document.status}</div>
        {document.chunks !== undefined && <div>Chunks: {document.chunks}</div>}
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px' }}>
        <button
          onClick={() => setShowChunks(!showChunks)}
          style={{
            padding: '6px 12px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '12px',
          }}
        >
          {showChunks ? 'Hide' : 'Show'} Chunks ({chunks.length})
        </button>
        {document.status !== 'indexed' && (
          <button
            onClick={() => window.knowledgeBase.indexing.start(document.id)}
            style={{
              padding: '6px 12px',
              background: '#533483',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Index Document
          </button>
        )}
        {onDelete && (
          <button
            onClick={() => onDelete(document.id)}
            style={{
              padding: '6px 12px',
              background: '#8b2252',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '12px',
            }}
          >
            Delete
          </button>
        )}
      </div>

      {/* Content viewer -- placeholder until document-detail feature is implemented */}
      {content && (
        <div style={{
          padding: '16px',
          background: '#1a1a3e',
          borderRadius: '6px',
          border: '1px solid #0f3460',
          fontSize: '13px',
          lineHeight: 1.6,
          whiteSpace: 'pre-wrap',
        }}>
          {content}
        </div>
      )}

      {showChunks && (
        <div>
          {chunks.map(chunk => (
            <div
              key={chunk.id}
              style={{
                padding: '10px',
                marginBottom: '8px',
                background: '#1a1a3e',
                borderRadius: '4px',
                borderLeft: '3px solid #533483',
                fontSize: '13px',
                lineHeight: 1.5,
              }}
            >
              <div style={{ fontSize: '11px', color: '#888', marginBottom: '4px' }}>
                Chunk {chunk.index} ({chunk.metadata.charCount} chars)
              </div>
              {chunk.content}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
import { useState, useCallback } from 'react';
import { DocumentList } from './components/DocumentList';
import { QuestionPanel } from './components/QuestionPanel';
import { DocumentDetail } from './components/DocumentDetail';
import { ImportPanel } from './components/ImportPanel';
import { StatusBar } from './components/StatusBar';
import { Document, AppStatus, QAResponse, ImportResult } from '../shared/types';

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedDoc, setSelectedDoc] = useState<Document | null>(null);
  const [appStatus, setAppStatus] = useState<AppStatus>({
    documentsLoaded: 0,
    indexStatus: 'idle',
    lastActivity: '',
  });
  const [lastResponse, setLastResponse] = useState<QAResponse | null>(null);
  const [showImport, setShowImport] = useState(false);

  const refreshDocuments = useCallback(async () => {
    try {
      const docs = await window.knowledgeBase.documents.list();
      setDocuments(docs);
      const status = await window.knowledgeBase.indexing.status();
      setAppStatus({
        documentsLoaded: docs.length,
        indexStatus: status.status,
        lastActivity: status.lastIndexed ?? '',
      });
      return docs;
    } catch (err) {
      console.error('Failed to refresh documents:', err);
      return null;
    }
  }, []);

  const handleImported = useCallback(async (result: ImportResult) => {
    await refreshDocuments();
    // Select the first newly imported document so the user sees it immediately.
    setSelectedDoc(result.imported[0] ?? null);
    // Keep the panel open when some files failed, so the errors stay visible.
    if (result.failed.length === 0) {
      setShowImport(false);
    }
  }, [refreshDocuments]);

  const handleSelectDocument = useCallback((doc: Document) => {
    setSelectedDoc(doc);
  }, []);

  const handleAskQuestion = useCallback(async (question: string) => {
    try {
      const response = await window.knowledgeBase.qa.ask(question);
      setLastResponse(response);
    } catch (err) {
      console.error('Q&A failed:', err);
    }
  }, []);

  const handleDeleteDocument = useCallback(async (id: string) => {
    try {
      await window.knowledgeBase.documents.delete(id);
      if (selectedDoc?.id === id) {
        setSelectedDoc(null);
      }
      await refreshDocuments();
    } catch (err) {
      console.error('Delete failed:', err);
    }
  }, [selectedDoc, refreshDocuments]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      <header style={{
        padding: '12px 20px',
        background: '#16213e',
        borderBottom: '1px solid #0f3460',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <h1 style={{ fontSize: '18px', fontWeight: 600 }}>Knowledge Base</h1>
        <button
          onClick={refreshDocuments}
          style={{
            padding: '6px 14px',
            background: '#0f3460',
            color: '#e0e0e0',
            border: '1px solid #1a1a4e',
            borderRadius: '4px',
            cursor: 'pointer',
            fontSize: '13px',
          }}
        >
          Refresh
        </button>
      </header>

      <div style={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
        {/* Left panel: Document list */}
        <div style={{
          width: '280px',
          borderRight: '1px solid #0f3460',
          display: 'flex',
          flexDirection: 'column',
          background: '#16213e',
        }}>
          <div style={{
            padding: '10px 16px',
            borderBottom: '1px solid #0f3460',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
          }}>
            <span style={{ fontSize: '13px', fontWeight: 500, color: '#a0a0c0' }}>
              Documents ({documents.length})
            </span>
            <button
              onClick={() => setShowImport(!showImport)}
              style={{
                padding: '4px 10px',
                background: '#533483',
                color: '#fff',
                border: 'none',
                borderRadius: '3px',
                cursor: 'pointer',
                fontSize: '12px',
              }}
            >
              + Import
            </button>
          </div>
          <DocumentList
            documents={documents}
            onSelect={handleSelectDocument}
            selectedId={selectedDoc?.id ?? null}
          />
        </div>

        {/* Right panel: Import, Document detail + Q&A */}
        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
          <div style={{ flex: 1, overflow: 'auto', padding: '20px' }}>
            {showImport ? (
              <ImportPanel onImported={handleImported} />
            ) : selectedDoc ? (
              <DocumentDetail
                document={selectedDoc}
                onDelete={handleDeleteDocument}
              />
            ) : (
              <div style={{ color: '#666', textAlign: 'center', paddingTop: '40px' }}>
                Select a document or ask a question to get started
              </div>
            )}
            {lastResponse && (
              <div style={{
                marginTop: '16px',
                padding: '16px',
                background: '#1a1a3e',
                borderRadius: '6px',
                border: '1px solid #0f3460',
              }}>
                <div style={{ fontSize: '14px', lineHeight: 1.6 }}>{lastResponse.answer}</div>
                {lastResponse.citations.length > 0 && (
                  <div style={{ marginTop: '10px', fontSize: '12px', color: '#8888bb' }}>
                    <strong>Citations:</strong>
                    {lastResponse.citations.map((c, i) => (
                      <div key={i} style={{ marginTop: '4px', paddingLeft: '8px', borderLeft: '2px solid #533483' }}>
                        {c.documentTitle} (chunk {c.chunkIndex}): {c.excerpt.substring(0, 100)}...
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          <QuestionPanel onAsk={handleAskQuestion} />
        </div>
      </div>

      <StatusBar status={appStatus} />
    </div>
  );
}
/// <reference types="react" />
/// <reference types="react-dom" />

import type {
  Chunk,
  Document,
  ImportResult,
  IndexStatus,
  QAHistory,
  QAResponse,
} from '../shared/types';

declare global {
  interface Window {
    knowledgeBase: {
      documents: {
        list: () => Promise<Document[]>;
        importWithDialog: () => Promise<ImportResult>;
        import: (filePaths: string[]) => Promise<ImportResult>;
        getPathForFile: (file: File) => string;
        get: (id: string) => Promise<Document | null>;
        delete: (id: string) => Promise<boolean>;
      };
      indexing: {
        start: (documentId?: string) => Promise<IndexStatus>;
        status: () => Promise<IndexStatus>;
        chunks: (documentId: string) => Promise<Chunk[]>;
      };
      qa: {
        ask: (question: string) => Promise<QAResponse>;
        history: () => Promise<QAHistory[]>;
      };
    };
  }
}

export {};
/** Cross-boundary type definitions shared between main, preload, and renderer. */

export interface Document {
  id: string;
  title: string;
  filename: string;
  importedAt: string;
  size: number;
  status: 'imported' | 'indexing' | 'indexed' | 'error';
  chunks?: number;
}

export interface Chunk {
  id: string;
  documentId: string;
  content: string;
  index: number;
  metadata: Record<string, string>;
}

export interface Citation {
  documentId: string;
  documentTitle: string;
  chunkIndex: number;
  excerpt: string;
}

export interface QAResponse {
  answer: string;
  citations: Citation[];
  confidence: number;
  timestamp: string;
}

export interface QAHistory {
  question: string;
  response: QAResponse;
}

/** Status returned by the indexing service. */
export interface IndexStatus {
  status: 'idle' | 'indexing' | 'ready' | 'error';
  currentIndexed: number;
  totalDocuments: number;
  lastIndexed: string | null;
}

/** File extensions accepted by document import (lowercase, with dot). */
export const SUPPORTED_EXTENSIONS = ['.txt', '.md'] as const;

/** Maximum size of an importable file, in bytes (10 MB). */
export const MAX_IMPORT_FILE_SIZE = 10 * 1024 * 1024;

export interface ImportFailure {
  /** Base name of the file that failed to import. */
  filename: string;
  /** Human-readable reason. */
  message: string;
}

/** Outcome of importing one or more files. Per-file failures do not abort the batch. */
export interface ImportResult {
  imported: Document[];
  failed: ImportFailure[];
  /** True when the user dismissed the file picker without choosing files. */
  canceled: boolean;
}

export interface AppStatus {
  documentsLoaded: number;
  indexStatus: 'idle' | 'indexing' | 'ready' | 'error';
  lastActivity: string;
}

/** IPC channel names -- single source of truth. */
export const IPC_CHANNELS = {
  // Document operations
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DOCUMENTS: 'documents:import',
  IMPORT_DOCUMENTS_DIALOG: 'documents:importDialog',
  GET_DOCUMENT: 'documents:get',
  DELETE_DOCUMENT: 'documents:delete',

  // Indexing
  START_INDEXING: 'indexing:start',
  GET_INDEXING_STATUS: 'indexing:status',
  GET_CHUNKS: 'indexing:chunks',

  // Q&A
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',

  // App status
  GET_STATUS: 'app:status',
} as const;
// NOTE: This file is bundled by esbuild (npm run build:preload) because the
// sandboxed preload cannot require() local modules such as ../shared/types.
import { contextBridge, ipcRenderer, webUtils } from 'electron';
import { IPC_CHANNELS } from '../shared/types';

const api = {
  documents: {
    list: () => ipcRenderer.invoke(IPC_CHANNELS.LIST_DOCUMENTS),
    /** Open the native file picker in the main process and import the selection. */
    importWithDialog: () => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENTS_DIALOG),
    /** Import files by absolute path (e.g. from drag-and-drop). */
    import: (filePaths: string[]) => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENTS, filePaths),
    /**
     * Resolve the on-disk path of a File from a drop event or file input.
     * File.path was removed in Electron 32; webUtils is the replacement.
     */
    getPathForFile: (file: File) => webUtils.getPathForFile(file),
    get: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_DOCUMENT, id),
    delete: (id: string) => ipcRenderer.invoke(IPC_CHANNELS.DELETE_DOCUMENT, id),
  },
  indexing: {
    start: (documentId?: string) => ipcRenderer.invoke(IPC_CHANNELS.START_INDEXING, documentId),
    status: () => ipcRenderer.invoke(IPC_CHANNELS.GET_INDEXING_STATUS),
    chunks: (documentId: string) => ipcRenderer.invoke(IPC_CHANNELS.GET_CHUNKS, documentId),
  },
  qa: {
    ask: (question: string) => ipcRenderer.invoke(IPC_CHANNELS.ASK_QUESTION, question),
    history: () => ipcRenderer.invoke(IPC_CHANNELS.GET_HISTORY),
  },
};

contextBridge.exposeInMainWorld('knowledgeBase', api);
import { BrowserWindow, dialog, IpcMain, OpenDialogOptions } from 'electron';
import { DocumentService } from '../services/document-service';
import { IndexingService } from '../services/indexing-service';
import { QaService } from '../services/qa-service';
import { IPC_CHANNELS, ImportResult, SUPPORTED_EXTENSIONS } from '../shared/types';

export interface Services {
  documentService: DocumentService;
  indexingService: IndexingService;
  qaService: QaService;
}

export function registerIpcHandlers(ipcMain: IpcMain, services: Services) {
  const { documentService, indexingService, qaService } = services;

  // Document operations
  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, async () => {
    return documentService.listDocuments();
  });

  // Import files the user dropped onto the window (paths resolved in preload).
  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENTS, async (_event, filePaths: unknown): Promise<ImportResult> => {
    if (!Array.isArray(filePaths) || !filePaths.every(p => typeof p === 'string')) {
      throw new Error('Expected an array of file paths');
    }
    return documentService.importDocuments(filePaths);
  });

  // Show the native file picker and import whatever the user selects.
  ipcMain.handle(IPC_CHANNELS.IMPORT_DOCUMENTS_DIALOG, async (event): Promise<ImportResult> => {
    const options: OpenDialogOptions = {
      title: 'Import Documents',
      buttonLabel: 'Import',
      properties: ['openFile', 'multiSelections'],
      filters: [
        { name: 'Text documents', extensions: SUPPORTED_EXTENSIONS.map(ext => ext.slice(1)) },
      ],
    };
    const win = BrowserWindow.fromWebContents(event.sender);
    const selection = win
      ? await dialog.showOpenDialog(win, options)
      : await dialog.showOpenDialog(options);

    if (selection.canceled || selection.filePaths.length === 0) {
      return { imported: [], failed: [], canceled: true };
    }
    return documentService.importDocuments(selection.filePaths);
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, async (_event, id: string) => {
    return documentService.getDocument(id);
  });

  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, async (_event, id: string) => {
    return documentService.deleteDocument(id);
  });

  // Indexing
  ipcMain.handle(IPC_CHANNELS.START_INDEXING, async (_event, documentId?: string) => {
    return indexingService.startIndexing(documentId);
  });

  ipcMain.handle(IPC_CHANNELS.GET_INDEXING_STATUS, async () => {
    return indexingService.getStatus();
  });

  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, async (_event, documentId: string) => {
    return indexingService.getChunksForDocument(documentId);
  });

  // Q&A
  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: string) => {
    return qaService.ask(question);
  });

  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, async () => {
    return qaService.getHistory();
  });
}
import * as fs from 'fs';
import * as path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { Document, ImportResult, MAX_IMPORT_FILE_SIZE, SUPPORTED_EXTENSIONS } from '../shared/types';
import { PersistenceService } from './persistence-service';

const DOCUMENTS_META = 'documents-meta.json';

export class DocumentService {
  private persistence: PersistenceService;

  constructor(persistence: PersistenceService) {
    this.persistence = persistence;
  }

  /** List all imported documents. */
  listDocuments(): Document[] {
    const docs = this.persistence.readJson<Document[]>(DOCUMENTS_META);
    return docs ?? [];
  }

  /**
   * Import several files. Each file is validated and imported independently,
   * so one bad file does not prevent the others from being imported.
   */
  importDocuments(filePaths: string[]): ImportResult {
    const result: ImportResult = { imported: [], failed: [], canceled: false };
    for (const filePath of filePaths) {
      try {
        result.imported.push(this.importDocument(filePath));
      } catch (err) {
        result.failed.push({
          filename: path.basename(filePath),
          message: err instanceof Error ? err.message : String(err),
        });
      }
    }
    return result;
  }

  /** Import a single .txt or .md file from the given absolute path. Throws on invalid input. */
  importDocument(filePath: string): Document {
    if (typeof filePath !== 'string' || filePath.length === 0) {
      throw new Error('No file path provided');
    }
    if (!path.isAbsolute(filePath)) {
      throw new Error('File path must be absolute');
    }

    const filename = path.basename(filePath);
    const ext = path.extname(filename).toLowerCase();
    if (!(SUPPORTED_EXTENSIONS as readonly string[]).includes(ext)) {
      throw new Error(`Unsupported file type "${ext || '(none)'}". Supported: ${SUPPORTED_EXTENSIONS.join(', ')}`);
    }

    let stats: fs.Stats;
    try {
      stats = fs.statSync(filePath);
    } catch {
      throw new Error('File not found');
    }
    if (!stats.isFile()) {
      throw new Error('Not a regular file');
    }
    if (stats.size > MAX_IMPORT_FILE_SIZE) {
      const mb = (stats.size / (1024 * 1024)).toFixed(1);
      throw new Error(`File is too large (${mb} MB). Maximum is ${MAX_IMPORT_FILE_SIZE / (1024 * 1024)} MB`);
    }

    const content = decodeText(fs.readFileSync(filePath));

    const id = uuidv4();
    const doc: Document = {
      id,
      title: deriveTitle(filename),
      filename,
      importedAt: new Date().toISOString(),
      size: stats.size,
      status: 'imported',
    };

    // Store the original under an ID-based name so two files with the same
    // name (from different folders) never overwrite each other.
    const storedName = storedFilename(doc);
    const contentPath = `content/${id}.txt`;
    try {
      this.persistence.copyFileToDocuments(filePath, storedName);
      this.persistence.writeText(contentPath, content);

      const docs = this.listDocuments();
      docs.push(doc);
      this.persistence.writeJson(DOCUMENTS_META, docs);
    } catch (err) {
      // Roll back partial writes so we don't leave orphaned files behind.
      this.persistence.deleteFromDocuments(storedName);
      this.persistence.deleteFile(contentPath);
      throw err;
    }

    return doc;
  }

  /** Get a single document by ID. */
  getDocument(id: string): Document | null {
    const docs = this.listDocuments();
    return docs.find(d => d.id === id) ?? null;
  }

  /** Get the text content of a document. */
  getDocumentContent(id: string): string | null {
    return this.persistence.readText(`content/${id}.txt`);
  }

  /** Update a document's metadata. */
  updateDocument(id: string, updates: Partial<Document>): Document | null {
    const docs = this.listDocuments();
    const index = docs.findIndex(d => d.id === id);
    if (index === -1) return null;

    docs[index] = { ...docs[index], ...updates };
    this.persistence.writeJson(DOCUMENTS_META, docs);
    return docs[index];
  }

  /** Delete a document by ID. */
  deleteDocument(id: string): boolean {
    const docs = this.listDocuments();
    const doc = docs.find(d => d.id === id);
    if (!doc) return false;

    this.persistence.deleteFromDocuments(storedFilename(doc));

    const updated = docs.filter(d => d.id !== id);
    this.persistence.writeJson(DOCUMENTS_META, updated);
    return true;
  }
}

/** Name of the copy kept in the data directory's documents/ folder. */
function storedFilename(doc: Document): string {
  return `${doc.id}${path.extname(doc.filename).toLowerCase()}`;
}

/** Title shown in the UI: the file name without its extension. */
function deriveTitle(filename: string): string {
  const base = filename.replace(/\.[^.]+$/, '').trim();
  return base.length > 0 ? base : filename;
}

/** Decode file bytes as UTF-8 text, rejecting binary or non-UTF-8 content. */
function decodeText(buffer: Buffer): string {
  if (buffer.includes(0)) {
    throw new Error('File appears to be binary, not text');
  }
  try {
    const text = new TextDecoder('utf-8', { fatal: true }).decode(buffer);
    return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  } catch {
    throw new Error('File is not valid UTF-8 text');
  }
}
import * as fs from 'fs';
import * as path from 'path';

export class PersistenceService {
  private dataDir: string;
  private documentsDir: string;
  private indexDir: string;

  constructor(dataDir: string) {
    this.dataDir = dataDir;
    this.documentsDir = path.join(dataDir, 'documents');
    this.indexDir = path.join(dataDir, 'index');
    this.ensureDirectories();
  }

  private ensureDirectories() {
    fs.mkdirSync(this.dataDir, { recursive: true });
    fs.mkdirSync(this.documentsDir, { recursive: true });
    fs.mkdirSync(this.indexDir, { recursive: true });
  }

  /** Read a JSON file, returning null if it doesn't exist. */
  readJson<T>(relativePath: string): T | null {
    const fullPath = path.join(this.dataDir, relativePath);
    if (!fs.existsSync(fullPath)) return null;
    return JSON.parse(fs.readFileSync(fullPath, 'utf-8'));
  }

  /** Write a JSON file atomically. */
  writeJson<T>(relativePath: string, data: T): void {
    const fullPath = path.join(this.dataDir, relativePath);
    const dir = path.dirname(fullPath);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(fullPath, JSON.stringify(data, null, 2), 'utf-8');
  }

  /** Read a text file. */
  readText(relativePath: string): string | null {
    const fullPath = path.join(this.dataDir, relativePath);
    if (!fs.existsSync(fullPath)) return null;
    return fs.readFileSync(fullPath, 'utf-8');
  }

  /** Write a text file. */
  writeText(relativePath: string, content: string): void {
    const fullPath = path.join(this.dataDir, relativePath);
    const dir = path.dirname(fullPath);
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(fullPath, content, 'utf-8');
  }

  /** Copy a file into the documents directory. */
  copyFileToDocuments(sourcePath: string, filename: string): string {
    const destPath = path.join(this.documentsDir, filename);
    fs.mkdirSync(this.documentsDir, { recursive: true });
    fs.copyFileSync(sourcePath, destPath);
    return destPath;
  }

  /** Delete a file from the documents directory. */
  deleteFromDocuments(filename: string): void {
    const filePath = path.join(this.documentsDir, filename);
    if (fs.existsSync(filePath)) {
      fs.unlinkSync(filePath);
    }
  }

  /** Delete a file relative to the data directory, if it exists. */
  deleteFile(relativePath: string): void {
    const fullPath = path.join(this.dataDir, relativePath);
    if (fs.existsSync(fullPath)) {
      fs.unlinkSync(fullPath);
    }
  }

  /** List all files in a directory. */
  listFiles(relativePath: string): string[] {
    const fullPath = path.join(this.dataDir, relativePath);
    if (!fs.existsSync(fullPath)) return [];
    return fs.readdirSync(fullPath);
  }

  /** Check if a file exists. */
  exists(relativePath: string): boolean {
    return fs.existsSync(path.join(this.dataDir, relativePath));
  }

  /** Get the data directory path. */
  getDataDir(): string {
    return this.dataDir;
  }

  /** Get the documents directory path. */
  getDocumentsDir(): string {
    return this.documentsDir;
  }

  /** Get the index directory path. */
  getIndexDir(): string {
    return this.indexDir;
  }
}
