/** Cross-boundary type definitions shared between main, preload, and renderer. */

export interface Document {
  id: string;
  title: string;
  filename: string;
  importedAt: string;
  size: number;
  status: 'imported' | 'indexing' | 'indexed' | 'error';
  chunks?: number;
}

export interface Chunk {
  id: string;
  documentId: string;
  content: string;
  index: number;
  metadata: Record<string, string>;
}

export interface Citation {
  documentId: string;
  documentTitle: string;
  chunkIndex: number;
  excerpt: string;
}

export interface QAResponse {
  answer: string;
  citations: Citation[];
  confidence: number;
  timestamp: string;
}

export interface QAHistory {
  question: string;
  response: QAResponse;
}

/** Status returned by the indexing service. */
export interface IndexStatus {
  status: 'idle' | 'indexing' | 'ready' | 'error';
  currentIndexed: number;
  totalDocuments: number;
  lastIndexed: string | null;
}

/** File extensions accepted by document import (lowercase, with dot). */
export const SUPPORTED_EXTENSIONS = ['.txt', '.md'] as const;

/** Maximum size of an importable file, in bytes (10 MB). */
export const MAX_IMPORT_FILE_SIZE = 10 * 1024 * 1024;

export interface ImportFailure {
  /** Base name of the file that failed to import. */
  filename: string;
  /** Human-readable reason. */
  message: string;
}

/** Outcome of importing one or more files. Per-file failures do not abort the batch. */
export interface ImportResult {
  imported: Document[];
  failed: ImportFailure[];
  /** True when the user dismissed the file picker without choosing files. */
  canceled: boolean;
}

export interface AppStatus {
  documentsLoaded: number;
  indexStatus: 'idle' | 'indexing' | 'ready' | 'error';
  lastActivity: string;
}

/** IPC channel names -- single source of truth. */
export const IPC_CHANNELS = {
  // Document operations
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DOCUMENTS: 'documents:import',
  IMPORT_DOCUMENTS_DIALOG: 'documents:importDialog',
  GET_DOCUMENT: 'documents:get',
  DELETE_DOCUMENT: 'documents:delete',

  // Indexing
  START_INDEXING: 'indexing:start',
  GET_INDEXING_STATUS: 'indexing:status',
  GET_CHUNKS: 'indexing:chunks',

  // Q&A
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',

  // App status
  GET_STATUS: 'app:status',
} as const;
