    /** Open the native file picker in the main process and import the selection. */
    importWithDialog: () => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENTS_DIALOG),
    /** Import files by absolute path (e.g. from drag-and-drop). */
    import: (filePaths: string[]) => ipcRenderer.invoke(IPC_CHANNELS.IMPORT_DOCUMENTS, filePaths),
    /**
