import { useEffect, useState } from 'react';
import { Document, Chunk } from '../../shared/types';

interface Props {
  document: Document;
  onDelete?: (id: string) => void;
}

type ContentState =
  | { kind: 'loading' }
  | { kind: 'loaded'; text: string }
  | { kind: 'missing' }
  | { kind: 'error'; message: string };

const buttonStyle = {
  padding: '6px 12px',
  border: 'none',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '12px',
} as const;

const panelStyle = {
  padding: '16px',
  background: '#1a1a3e',
  borderRadius: '6px',
  border: '1px solid #0f3460',
  fontSize: '13px',
  lineHeight: 1.6,
} as const;

export function DocumentDetail({ document, onDelete }: Props) {
  const [chunks, setChunks] = useState<Chunk[]>([]);
  const [showChunks, setShowChunks] = useState(false);
  const [content, setContent] = useState<ContentState>({ kind: 'loading' });
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    // Ignore responses that arrive after the user switched to another document.
    let current = true;
    setContent({ kind: 'loading' });
    setChunks([]);
    setShowChunks(false);
    setConfirmingDelete(false);
    setDeleting(false);

    window.knowledgeBase.documents.getContent(document.id).then(
      text => {
        if (current) setContent(text === null ? { kind: 'missing' } : { kind: 'loaded', text });
      },
      (err: unknown) => {
        if (current) {
          setContent({ kind: 'error', message: err instanceof Error ? err.message : String(err) });
        }
      },
    );
    window.knowledgeBase.indexing.chunks(document.id).then(
      result => { if (current) setChunks(result); },
      (err: unknown) => console.error('Failed to load chunks:', err),
    );

    return () => { current = false; };
  }, [document.id]);

  const handleConfirmDelete = async () => {
    if (!onDelete) return;
    setDeleting(true);
    try {
      await onDelete(document.id);
    } finally {
      setDeleting(false);
      setConfirmingDelete(false);
    }
  };

  const wordCount = content.kind === 'loaded'
    ? content.text.split(/\s+/).filter(Boolean).length
    : null;

  return (
    <div>
      <h2 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '8px', overflowWrap: 'anywhere' }}>
        {document.title}
      </h2>
      <div style={{ fontSize: '13px', color: '#888', marginBottom: '16px' }}>
        <div>Filename: {document.filename}</div>
        <div>Imported: {new Date(document.importedAt).toLocaleString()}</div>
        <div>Size: {(document.size / 1024).toFixed(1)} KB</div>
        {wordCount !== null && <div>Words: {wordCount.toLocaleString()}</div>}
        <div>Status: {document.status}</div>
        {document.chunks !== undefined && <div>Chunks: {document.chunks}</div>}
      </div>

      <div style={{ display: 'flex', gap: '8px', marginBottom: '16px', flexWrap: 'wrap', alignItems: 'center' }}>
        <button
          onClick={() => setShowChunks(!showChunks)}
          style={{ ...buttonStyle, background: '#0f3460', color: '#e0e0e0', border: '1px solid #1a1a4e' }}
        >
          {showChunks ? 'Hide' : 'Show'} Chunks ({chunks.length})
        </button>
        {document.status !== 'indexed' && (
          <button
            onClick={() => window.knowledgeBase.indexing.start(document.id)}
            style={{ ...buttonStyle, background: '#533483', color: '#fff' }}
          >
            Index Document
          </button>
        )}
        {onDelete && !confirmingDelete && (
          <button
            onClick={() => setConfirmingDelete(true)}
            style={{ ...buttonStyle, background: '#8b2252', color: '#fff' }}
          >
            Delete
          </button>
        )}
        {onDelete && confirmingDelete && (
          <>
            <span style={{ fontSize: '12px', color: '#e0a0b0' }}>
              Delete “{document.title}” and its indexed data?
            </span>
            <button
              onClick={handleConfirmDelete}
              disabled={deleting}
              style={{ ...buttonStyle, background: '#c0392b', color: '#fff', opacity: deleting ? 0.6 : 1 }}
            >
              {deleting ? 'Deleting…' : 'Confirm Delete'}
            </button>
            <button
              onClick={() => setConfirmingDelete(false)}
              disabled={deleting}
              style={{ ...buttonStyle, background: 'transparent', color: '#e0e0e0', border: '1px solid #0f3460' }}
            >
              Cancel
            </button>
          </>
        )}
      </div>

      {showChunks && (
        <div style={{ marginBottom: '16px' }}>
          {chunks.length === 0 && (
            <div style={{ fontSize: '13px', color: '#888' }}>
              No chunks yet. Index the document to create them.
            </div>
          )}
          {chunks.map(chunk => (
            <div
              key={chunk.id}
              style={{
                padding: '10px',
                marginBottom: '8px',
                background: '#1a1a3e',
                borderRadius: '4px',
                borderLeft: '3px solid #533483',
                fontSize: '13px',
                lineHeight: 1.5,
                whiteSpace: 'pre-wrap',
              }}
            >
              <div style={{ fontSize: '11px', color: '#888', marginBottom: '4px' }}>
                Chunk {chunk.index} ({chunk.metadata.charCount} chars)
              </div>
              {chunk.content}
            </div>
          ))}
        </div>
      )}

      <h3 style={{ fontSize: '14px', fontWeight: 600, color: '#a0a0c0', marginBottom: '8px' }}>Content</h3>
      {content.kind === 'loading' && (
        <div style={{ ...panelStyle, color: '#888' }}>Loading content…</div>
      )}
      {content.kind === 'missing' && (
        <div style={{ ...panelStyle, color: '#e0a0b0' }}>
          The stored content for this document could not be found.
        </div>
      )}
      {content.kind === 'error' && (
        <div style={{ ...panelStyle, color: '#e0a0b0' }}>
          Failed to load content: {content.message}
        </div>
      )}
      {content.kind === 'loaded' && (
        <div
          data-testid="document-content"
          style={{ ...panelStyle, whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}
        >
          {content.text.length > 0
            ? content.text
            : <span style={{ color: '#888' }}>This document is empty.</span>}
        </div>
      )}
    </div>
  );
}

