const { app, dialog, BrowserWindow } = require('electron');
const path = require('path'); const fs = require('fs'); const os = require('os');
const root = process.env.ROOT;
const ud = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-e2e-'));
app.setPath('userData', ud);
const samples = path.join(root, 'data/sample-documents');
dialog.showOpenDialog = async () => ({ canceled: false, filePaths: fs.readdirSync(samples).map(f => path.join(samples, f)) });
require(path.join(root, 'dist/main/main.js'));
const sleep = ms => new Promise(r => setTimeout(r, ms));
app.whenReady().then(async () => {
  await sleep(1500);
  const win = BrowserWindow.getAllWindows()[0];
  const js = s => win.webContents.executeJavaScript(s);
  const click = txt => js(`(()=>{const b=[...document.querySelectorAll('button,div')].reverse().find(e=>e.textContent.trim()===${JSON.stringify(txt)});if(!b)return false;b.click();return true})()`);
  const out = {};
  try {
    await click('+ Import'); await sleep(300);
    out.importBtn = await js(`(()=>{const b=[...document.querySelectorAll('button')].find(b=>/choose|browse|select|import/i.test(b.textContent)&&b.textContent.trim()!=='+ Import');b&&b.click();return b&&b.textContent})()`);
    await sleep(800);
    out.heading = await js(`document.querySelector('h2')?.textContent`);
    const dc = await js(`document.querySelector('[data-testid=document-content]')?.textContent`);
    const doc = fs.readFileSync(path.join(ud,'knowledge-base-data/documents-meta.json'),'utf-8'); const metas = JSON.parse(doc);
    const sel = metas.find(m => m.title === out.heading);
    out.contentMatchesFile = sel ? dc === fs.readFileSync(path.join(samples, sel.filename), 'utf-8') : 'no-sel';
    out.metaText = await js(`document.querySelector('h2').nextElementSibling.innerText`);
    // switch documents
    const other = metas.find(m => m !== sel);
    await click(other.title); await sleep(500);
    const dc2 = await js(`document.querySelector('[data-testid=document-content]')?.textContent`);
    out.switchMatches = dc2 === fs.readFileSync(path.join(samples, other.filename), 'utf-8');
    // index then delete
    await click('Index Document'); await sleep(400);
    out.chunkFileBefore = fs.existsSync(path.join(ud,'knowledge-base-data/chunks',other.id+'.json'));
    await click('Delete'); await sleep(200);
    out.confirmShown = await js(`document.body.innerText.includes('Confirm Delete')`);
    await click('Cancel'); await sleep(200);
    out.afterCancelStillThere = await js(`document.querySelector('h2')?.textContent`) === other.title;
    await click('Delete'); await sleep(200); await click('Confirm Delete'); await sleep(600);
    out.afterDeleteHeading = await js(`document.querySelector('h2')?.textContent ?? null`);
    out.sidebarCount = await js(`[...document.querySelectorAll('span')].find(s=>s.textContent.startsWith('Documents ('))?.textContent`);
    const d = path.join(ud,'knowledge-base-data');
    out.leftovers = ['content/'+other.id+'.txt','chunks/'+other.id+'.json'].filter(f=>fs.existsSync(path.join(d,f)))
      .concat(fs.readdirSync(path.join(d,'documents')).filter(f=>f.startsWith(other.id)));
    out.metaCount = JSON.parse(fs.readFileSync(path.join(d,'documents-meta.json'))).length;
  } catch (e) { out.error = String(e && e.stack || e); }
  console.log('E2E ' + JSON.stringify(out, null, 1));
  fs.rmSync(ud, { recursive: true, force: true });
  app.exit(0);
});
EOF
